ALTER POLICY "engagement_entry_read" ON "engagement_entries" TO public USING (exists(select 1 from engagements e where e.id="engagement_entries"."engagement_id" and e.organization_id="engagement_entries"."organization_id" and e.project_id="engagement_entries"."project_id" and (exists(select 1 from memberships m where m.organization_id=e.organization_id and m.user_id=(select current_setting('borderless.user_id',true)) and m.role in ('Owner','Admin','Member','Viewer')) or (e.expert_user_id=(select current_setting('borderless.user_id',true)) and e.status in ('Active','Completed') and e.payload->>'contractStatus'='Confirmed' and e.payload->>'companyAgreed'='true' and e.payload->>'expertAgreed'='true' and e.payload->>'conflictStatus'='Cleared' and exists(select 1 from expert_profiles p where p.id=e.expert_id and p.user_id=(select current_setting('borderless.user_id',true)) and p.status='Verified') and e.revoked_at is null and (e.access_expires_at is null or e.access_expires_at>now())))));--> statement-breakpoint
