ALTER POLICY "engagement_event_create" ON "engagement_events" TO public WITH CHECK ("engagement_events"."actor_id"=(select current_setting('borderless.user_id',true)) and (exists(select 1 from engagements e where e.id="engagement_events"."engagement_id" and e.organization_id="engagement_events"."organization_id" and e.project_id="engagement_events"."project_id" and (exists(select 1 from memberships m where m.organization_id=e.organization_id and m.user_id=(select current_setting('borderless.user_id',true)) and m.role in ('Owner','Admin','Member')) or (e.expert_user_id=(select current_setting('borderless.user_id',true)) and e.status in ('Active') and e.payload->>'contractStatus'='Confirmed' and e.payload->>'companyAgreed'='true' and e.payload->>'expertAgreed'='true' and e.payload->>'conflictStatus'='Cleared' and exists(select 1 from expert_profiles p where p.id=e.expert_id and p.user_id=(select current_setting('borderless.user_id',true)) and p.status='Verified') and e.revoked_at is null and (e.access_expires_at is null or e.access_expires_at>now())))) or exists(select 1 from engagements e where e.id="engagement_events"."engagement_id" and e.organization_id="engagement_events"."organization_id" and e.project_id="engagement_events"."project_id" and ((e.expert_user_id=(select current_setting('borderless.user_id',true)) and e.status<>'Draft' and e.revoked_at is null and (e.access_expires_at is null or e.access_expires_at>now()) and exists(select 1 from expert_profiles p where p.id=e.expert_id and p.user_id=(select current_setting('borderless.user_id',true)) and p.status in ('Pending Verification','Verified'))) and e.status in ('Submitted','Accepted','Agreement Pending','Declined') and "engagement_events"."action" in ('engagement.accepted','engagement.declined','engagement.quoted','engagement.agreed','engagement.conflict_updated','engagement.canceled') and ("engagement_events"."payload" - 'from' - 'to') = '{}'::jsonb or ((select current_setting('borderless.expert_reviewer',true)) = 'on' and e.id=(select current_setting('borderless.review_engagement_id',true)) and e.status='Active' and "engagement_events"."action"='engagement.activated')))));--> statement-breakpoint
